    enonce: "<span class=\"q\">1) </span>بيّن أنّ العددين <span dir=\"ltr\" class=\"expr\">a = 2 + √6</span> و <span dir=\"ltr\" class=\"expr\">b = (2 - √6)/-2</span> مقلوبان<br><span class=\"q\">2) </span>بيّن أنّ العددين <span dir=\"ltr\" class=\"expr\">a = 2 + √6</span> و <span dir=\"ltr\" class=\"expr\">b = (2 - √6)/-2</span> <span dir=\"ltr\" class=\"expr\">a = 1 + √5</span> <span dir=\"ltr\" class=\"expr\">b = (1 - √5)/-4</span> مقلوبان<br><span class=\"q\">3) </span>بيّن أنّ العددين <span dir=\"ltr\" class=\"expr\">a = 2 + √6</span> و <span dir=\"ltr\" class=\"expr\">b = (2 - √6)/-2</span> <span dir=\"ltr\" class=\"expr\">a = 1 + √5</span> <span dir=\"ltr\" class=\"expr\">b = (1 - √5)/-4</span> مقلوبان",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"ما معنى مقلوبان","math":"عددان مقلوبان إذا كان جداؤهما يساوي 1"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">a × b = (2 + √6) × (2 - √6)/-2</span>"},{"quoi":"نستعمل المرافق","math":"<span dir=\"ltr\" class=\"expr\">(2 + √6)(2 - √6) = 4 - 6</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">4 - 6 = -2</span>"},{"quoi":"نقسم على -2","math":"<span dir=\"ltr\" class=\"expr\">-2/-2 = 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a × b = 1</span> إذن العددان مقلوبان"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ما معنى مقلوبان","math":"عددان مقلوبان إذا كان جداؤهما يساوي 1"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">a × b = (1 + √5) × (1 - √5)/-4</span>"},{"quoi":"نستعمل المرافق","math":"<span dir=\"ltr\" class=\"expr\">(1 + √5)(1 - √5) = 1 - 5</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">1 - 5 = -4</span>"},{"quoi":"نقسم على -4","math":"<span dir=\"ltr\" class=\"expr\">-4/-4 = 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a × b = 1</span> إذن العددان مقلوبان"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ما معنى مقلوبان","math":"عددان مقلوبان إذا كان جداؤهما يساوي 1"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">a × b = (1 + √5) × (1 - √5)/-4</span>"},{"quoi":"نستعمل المرافق","math":"<span dir=\"ltr\" class=\"expr\">(1 + √5)(1 - √5) = 1 - 5</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">1 - 5 = -4</span>"},{"quoi":"نقسم على -4","math":"<span dir=\"ltr\" class=\"expr\">-4/-4 = 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a × b = 1</span> إذن العددان مقلوبان"}],
