    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"ما معنى مقلوبان","math":"عددان مقلوبان إذا كان جداؤهما يساوي 1"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">a × b = (2 + √3) × (2 - √3)</span>"},{"quoi":"نستعمل المرافق","math":"<span dir=\"ltr\" class=\"expr\">(2 + √3)(2 - √3) = 4 - 3</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">4 - 3 = 1</span>"},{"quoi":"الجداء يساوي 1","math":"الجداء يساوي 1 مباشرة"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a × b = 1</span> إذن العددان مقلوبان"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ما معنى مقلوبان","math":"عددان مقلوبان إذا كان جداؤهما يساوي 1"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">a × b = (1 + √2) × (1 - √2)/-1</span>"},{"quoi":"نستعمل المرافق","math":"<span dir=\"ltr\" class=\"expr\">(1 + √2)(1 - √2) = 1 - 2</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">1 - 2 = -1</span>"},{"quoi":"نقسم على -1","math":"<span dir=\"ltr\" class=\"expr\">-1/-1 = 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a × b = 1</span> إذن العددان مقلوبان"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ما معنى مقلوبان","math":"عددان مقلوبان إذا كان جداؤهما يساوي 1"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">a × b = (2 + √5) × (2 - √5)/-1</span>"},{"quoi":"نستعمل المرافق","math":"<span dir=\"ltr\" class=\"expr\">(2 + √5)(2 - √5) = 4 - 5</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">4 - 5 = -1</span>"},{"quoi":"نقسم على -1","math":"<span dir=\"ltr\" class=\"expr\">-1/-1 = 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a × b = 1</span> إذن العددان مقلوبان"}],
